const payload = $json.body || {};
const theme = payload.theme || 'Inovação e Soberania Digital';
const tone = payload.tone || 'Cinematográfico Paulistano';

const correlationId = 'MEDIA-' + Date.now().toString(36).toUpperCase();

return [{
  json: {
    correlationId,
    theme,
    tone,
    timestamp: new Date().toISOString(),
    voiceParams: {
      model: 's2.1-pro-free',
      voice: 'minha-voz',
      temperature: 0.85,
      top_p: 0.88
    }
  }
}];
